function getJapaneseBehaviors() {
  const behaviors = ["eating sushi all day", "constantly bowing", "obsessed with anime", "working overtime every day"];
  return behaviors[Math.floor(Math.random() * behaviors.length)];
}

이 코드를 실행하면 예상한 결과가 나오지 않습니다. 일본 사람들의 일반적인 행동을 유머러스하게 보여주고 싶은데, 어떤 문제가 있는지 알려주실 수 있나요?
